sql_query:
SELECT "Primary endpoint"
FROM clinical_trials
WHERE "Cancer type" = 'Melanoma' AND "Included in MA" = 'No' AND "Name of ICI" = 'Ipilimumab';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Primary endpoint" AS source_value FROM clinical_trials WHERE "Cancer type" = 'Melanoma' AND "Included in MA" = 'No' AND "Name of ICI" = 'Ipilimumab'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_primary_endpoint_category(source_value) AS "primary_endpoint_category"
FROM base;
